计算平均相对误差MRE 
function [ MRE,what,dd ] = ccc( dataa,time ) 
what=[]; 
data=dataa; 
data(find(data==0))=[]; 
data=flipud(data); 
ccc=[]; 
a=[]; 
n1=length(data); 
cha=data(1:n1-1)-data(2:n1); 
num=find(abs(cha)<=0.005); 
n2=length(num); 
for i=1:n2-230 
if num(i+230)==num(i)+230 
a=1; 
ccc=[ccc a]; 
else 
a=0; 
ccc=[ccc a]; 
end 
end 

who=find(ccc==1); 
dd=who(1); 
what=num(dd:dd+230); 

n3=what(1);

n4=what(length(what)); 
[ x,y,p ] = xxyyfit( time,dataa ); 
yy=polyval(p,x); 
MRE=mean(abs(yy(n3:n4)-y(n3:n4))./y(n3:n4)); 

end 

预测电压为9.8V时，电池的剩余放电时间 
function [ EP,T] = EveryT( data1,time ) 
EP=[]; 
for i=1:9 
 ele=data1(:,i); 
 time; 
 [ x,y,p ] = xxyyfit( time,ele ); 
 EP=[EP;p]; 
end 
V=[0.64 0.8 1]'; 
T=60*24*EP*V; 
end 

筛选间隔不超过0.005 的样本点并计数 
function [ num,N ] = MreNum( data ) 

ele={}; 
num={}; 
for i=1:9 
 ele{i}=data(:,i); 
 ele{i}(find(ele{i}==0))=[]; 
 n=length(ele{i}); 
 mid=ele{i}(1:n-1)-ele{i}(2:n); 
 num{i}=find(abs(mid)<=0.005); 
end 

N=[]; 
for i=1:9 
 N=[N length(num{i})]; 
end 

end 


计算任一电流和电压下的电池放电时间 
function [tfit ] = TT( data,II )

data(find(data)==0)=[]; 
n=length(data); 
tfit=[]; 
for i=1:n 
I=II; 
U=data(i); 
T=(0.4227*log(I)-2.103)*U^2+(-7.549*log(I)+37.62)*U+32.38*log(I)-161.9; 
tfit=[tfit;T]; 
end 
end 

预测附件2 中电池衰减状态3 的剩余放电时间 
function [ tfit ] = Q3ans( Q3 ) 
change1=Q3(:,2)-Q3(:,3); 
change2=Q3(:,3)-Q3(:,4); 
rate1=change2./change1; 

change3=Q3(:,4)-Q3(:,5); 
rate2=change3./change2; 

rate2(isnan(rate2)==1)=[]; 
n=length(rate2); 
rate=mean(rate2(101:n)); 

N=length(change2); 
BaseChange=change2(n+1:N); 
BaseNum=Q3(n+1:N,4); 
tfit=BaseNum-BaseChange*rate; 

x=Q3(:,1); 
y1=Q3(:,2); 
y2=Q3(:,3); 
y3=Q3(:,4); 
y4=Q3(:,5); 
y4(isnan(y4)==1)=[]; 

plot(x,y1) 
hold on 
plot(x,y2,'g') 
plot(x,y3,'y') 
plot(x(1:148),y4,'k') 
plot(x(149:301),tfit,'r') 
end
